package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
//
// The original implementation walked the input one byte at a time in a single
// loop, tracking state with several intertwined flags (header, list,
// listOpened, he) and special-casing the final newline. Because markdown
// constructs (headers, list items, paragraphs) are line-oriented, the rewrite
// splits the input into lines and classifies each one. The only state carried
// across lines is whether the output is currently inside a <ul>.
func Render(markdown string) string {
	// Convert the first bold and italic markers to HTML tags up front, exactly
	// as the original implementation did with a global replacement before
	// parsing. (Only the first pair of each marker is converted.)
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	markdown = strings.Replace(markdown, "_", "</em>", 1)

	var html strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		if line == "" {
			continue
		}

		switch {
		case strings.HasPrefix(line, "#"):
			// A header line, unless it has seven or more '#' characters, in
			// which case it is rendered as a paragraph.
			if level := headerLevel(line); level >= 7 {
				writeParagraph(&html, line)
			} else {
				html.WriteString(fmt.Sprintf("<h%d>%s</h%d>", level, headerText(line), level))
			}
		case strings.HasPrefix(line, "* "):
			// A list item. Open the <ul> on the first item and close the
			// previous <li> on subsequent ones.
			if inList {
				html.WriteString("</li>")
			} else {
				html.WriteString("<ul>")
			}
			html.WriteString("<li>" + line[2:])
			inList = true
		default:
			// Plain text: close any open list, then emit a paragraph.
			if inList {
				html.WriteString("</li></ul>")
				inList = false
			}
			writeParagraph(&html, line)
		}
	}

	if inList {
		html.WriteString("</li></ul>")
	}

	return html.String()
}

// headerLevel counts the leading '#' characters in a header line.
func headerLevel(line string) int {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	return level
}

// headerText returns the text of a header line, dropping the leading '#'
// characters and a single following space.
func headerText(line string) string {
	return strings.TrimPrefix(line[headerLevel(line):], " ")
}

// writeParagraph appends text wrapped in <p> tags to html.
func writeParagraph(html *strings.Builder, text string) {
	html.WriteString("<p>" + text + "</p>")
}

